// Light course index for the website pages (landing, curriculum, boards, educators…).
// Same shape as src/lessons/index.js for the fields those pages use, without any lesson code.
// Generated by scripts/build-catalog.mjs.
import data from './catalog.json';

export const TRACKS = data.tracks;
export const BOARD_INFO = data.boards;
export const lessons = [];
for (const t of TRACKS) {
  t.lessons.forEach((l, i) => {
    l.track = t;
    l.indexInTrack = i;
    l.quiz = new Array(l.quizCount).fill(null);
    l.challenges = new Array(l.challengeCount).fill(null);
    lessons.push(l);
  });
}
